// n8n may hand the id list over as one array item or as one item per id
const raw = $input.all().map(i => i.json);
const ids = raw.length === 1 && Array.isArray(raw[0])
  ? raw[0]
  : raw.map(x => (x !== null && typeof x === 'object' ? (x.data ?? x.id) : x));
const top20 = (Array.isArray(ids) ? ids : []).slice(0, 20);
const items = [];
for (const id of top20) {
  try {
    const resp = await this.helpers.httpRequest({ url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`, timeout: 5000 });
    if (resp && resp.title) items.push({ id: resp.id, title: resp.title, url: resp.url || '', score: resp.score || 0, comments: resp.descendants || 0, by: resp.by || '' });
  } catch(e) {}
}
return [{ json: { items } }];

