const input = $input.first().json;
const raw = input.content?.[0]?.text || input.text || '[]';
let items;
try {
  const cleaned = raw.replace(/^```json/m, '').replace(/^```/m, '').replace(/```$/m, '').trim();
  items = JSON.parse(cleaned);
} catch(e) {
  try {
    const match = raw.match(/\[\s*\{.*\}\s*\]/s);
    items = match ? JSON.parse(match[0]) : [];
  } catch(e2) { items = []; }
}
return [{ json: { items: Array.isArray(items) ? items.slice(0, 10) : [] } }];

const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';
const data = $input.first().json;
const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));
let stored = 0;
for (const item of (data.items || [])) {
  try {
    db.run('INSERT INTO opportunities (source, title, url, summary, relevance_score, category, tags) VALUES (?, ?, ?, ?, ?, ?, ?)',
      [item.source || 'unknown', item.title || '', item.url || '', item.summary || '', item.score || 0, 'news', JSON.stringify([])]);
    stored++;
  } catch(e) {}
}
fs.writeFileSync(DB_PATH + '.tmp', Buffer.from(db.export())); fs.renameSync(DB_PATH + '.tmp', DB_PATH);
db.close();
return [{ json: { ...data, stored } }];

